    "verify_code": "answer = {'condition': 'closed/isolated', 'quantity': 'total'}\nprint(f\"In a/an {answer['condition']} system, the {answer['quantity']} linear momentum is conserved.\")",
    "techniques": ["given_formula_substitute_answer", "concept_map"]
  }
