    "final_answer": "Radial field lines pointing outwards",
    "verify_code": "import sympy as sp\nq = sp.Rational(6, 1) * 10**-6\n# Electric field direction for positive point charge is radially outward\n# E = k*q/r^2 * r_hat ; sign of q determines direction\nE_direction = 'outwards' if q > 0 else 'inwards'\nprint(E_direction)",
    "techniques": ["given_formula_substitute_answer", "particle_diagram"]
  }
}

